def norm_piece(p):
    minr=min(r for r,c in p); minc=min(c for r,c in p)
    return {(r-minr,c-minc):v for (r,c),v in p.items()}
def rots(p, allow_reflect=False):
    forms=[]
    base=norm_piece(p)
    for flip in ([False,True] if allow_reflect else [False]):
      q=base
      if flip: q={(r,-c):v for (r,c),v in q.items()}; q=norm_piece(q)
      for _ in range(4):
        q=norm_piece(q)
        sig=tuple(sorted(q.items()))
        if sig not in [s for s,_ in forms]: forms.append((sig,q))
        q={(c,-r):v for (r,c),v in q.items()}
    return [q for _,q in forms]
