def comp_sizes(cells):
  left=set(cells); out=[]
  while left:
    st=[left.pop()]; comp=set(st)
    while st:
      r,c=st.pop()
      for p in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
        if p in left: left.remove(p); st.append(p); comp.add(p)
    out.append(comp)
  return sorted([len(x) for x in out],reverse=True)
