def find_partial(forms, singles, limit=20):
  pls={}
  for name,fs in forms.items():
    cand=[]
    for oi,p in enumerate(fs):
      h=max(r for r,c in p)+1; w=max(c for r,c in p)+1
      for r0 in range(9-h+1):
       for c0 in range(20-w+1):
        cs=frozenset((r+r0,c+c0) for r,c in p)
        if cs<=mask:cand.append((cs,name,oi,r0,c0,p))
    pls[name]=cand
  bypiece={**pls}
  for n,val in singles:
    bypiece[n]=[(frozenset({cell}),n,0,*cell,{(0,0):val}) for cell in mask]
  names=list(bypiece); sols=[]
  # recursively choose most constrained remaining piece after updates
  def rec(cov, left, chosen):
    if not left:
      sols.append(chosen.copy()); return len(sols)>=limit
    best=None;optsbest=None
    for n in left:
      opts=[x for x in bypiece[n] if not x[0]&cov]
      if optsbest is None or len(opts)<len(optsbest): best=n;optsbest=opts
      if not opts:return False
    for x in optsbest:
      chosen.append(x)
      if rec(cov|x[0],left-{best},chosen):return True
      chosen.pop()
    return False
  rec(set(),set(names),[])
  return sols,{k:len(v) for k,v in bypiece.items()}
